#!/usr/bin/env python3
"""Writes the Assassin's re-skin prompts for the animations after the idle and Permafrost Execution (2026-11-05, "let's create the rest of the animations").

For every animation it takes the generic pose-guided prompt that make_pose_guides.py wrote (reskin/Rogue_<animation>/prompt.txt), fills in the Assassin's description
(Animations/Assassin/source/assassin_description.txt), adds the arm and eye poses panel by panel (a silhouette cannot show which arm crosses which or whether a hand is open; the poses come from the
Rogue's original prompts, adapted: a cape instead of a cloak and a scarf, no mouth because of the mask, and no "wrapped in the cloak" style actions) and writes prompt_assassin_sheet.txt next to the guides.
Run again after changing the description or a pose text, then rebuild the kit (make_reskin_kit.py).

  python Animations/Assassin/source/make_assassin_prompts.py [animation ...]      (only the named ones, e.g. static_stiletto; none = all)
"""
import pathlib
import re
import sys

ROOT = pathlib.Path(__file__).resolve().parents[3]
DESC = (ROOT / "Animations/Assassin/source/assassin_description.txt").read_text(encoding="utf-8").strip()

MASK = ("Her mouth is hidden by the mask: show every expression with the eyes, the brow and the tilt of the head only. Image 1's ready stance (the low calm stance, the far fist swung back behind the hip, "
        "the near fist low in front of the thigh) is what 'the ready stance' means below.")

